  "Оборотень копит молнии! Пробейте его, пока удар не упал.": "The Shape Shifter is gathering lightning! Break its Weakness before the strike lands.",
  "Фантилия выбрала цель! Лотосы Разрушения цветут. Пробейте или уничтожьте их!": "Phantylia has locked onto a target! Destruction Lotuses are blooming. Break or destroy them!",
  "Гнев зимних святых": "Wrath of Winterland Saints",
  "Коколия копит гнев зимних святых! Следом ударит Кара бесконечной зимы.": "Cocolia is gathering the Wrath of Winterland Saints! Punishment of Endless Winter will strike next.",
