  "Медикаменты, которые срочно нужны Наташе. «Полная коробка металлических пластин и бинтов, именно то, что нужно Наташе».": "Medical supplies urgently needed by Natasha.\n\n\"A full box of metal plates and bandages, exactly what Natasha needs.\"",
  "Коробка с медикаментами, которые срочно нужны Наташе. «Коробка медицинского спирта. Надеюсь, он не слишком сильно выветрился...»": "A box of medical supplies urgently needed by Natasha. \"Rubbing alcohol — hope it hasn't evaporated too much...\"",
  "Детская игрушка Брони. Снежная сова кружит над снежными полями, выискивая зайцев. «Даже если мы потеряли связь с прошлым, некоторые вещи всё ещё могут дополнить нас».": "Bronya's toy as a child. The snowy owl circles above the snowfields, looking for the best opportunity to hunt the hare. \"Even if our connection with the past is completely broken, there are still things that can complete us.\"",
