  "Рынок слишком непредсказуем...": "The market is unpredictable...",
  "Зверь или демон, я всех сокрушу!": "Fiends or devils, I'll crush them all!",
  "Пока не увижу это сияние ещё раз...": "Until I see that light once more...",
  "Любопытство, знаете ли, опасная штука.": "Curiosity... is a dangerous thing, you know.",
  "Вперёд, оседлав западный ветер~": "It's time to head out with the west wind!",
  "Всегда": "Always!",
  "Выкл.": "Off",
  "Тогда отправляемся.": "Now, should we hit the road?",
  "Держи темп.": "Keep up with the tempo!",
  "Давно не виделись... наставник.": "It's been a while... Master.",
  "Луна прольёт свет на правду.": "The moon shines on the truth.",
  "Помни, Яньцин: сначала думай, потом делай.": "Remember, Yanqing — think before you act.",
  "Удар наудачу!": "Luck of the draw...!",
  "Не бойтесь.": "Show no fear.",
  "Прими-ка витаминку.": "Gotta get those vitamins.",
  "Именем и волей десяти владык...": "By the will of the Ten Lords...",
  "П-привет, я Хохо, новая судья Комиссии десяти владык.": "Huohuo: H—Hello, I'm Huohuo, the newly appointed judge of the Ten-Lords Commission.",
  "Луна": "The moon...",
  "Хватит работать! Пора писать песни!": "Signing off now! Time to get some songwriting going~",
  "Бой, по сути, серия точных расчётов.": "Combat is a series of precise machinations.",
  "Я выращиваю цветы, но… получается не очень.": "I grow flowers, *sigh* ...It's just that I'm not very good at it.",
  "Я с-с-совсем тебя не боюсь!": "I—I'm not afraid of you!",
  "Томоэ": "Tomoe",
  "Конохана Сакуя": "Konohana Sakuya",
  "Такэ-Микадзути": "Take-Mikazuchi",
