  "Аматэрасу": "Amaterasu",
  "Рокутэн Мао": "Rokuten Maoh",
  "Кандзэон": "Kanzeon",
  "Невероятно!": "Absolutely stunning!",
  "Новые приключения, новые друзья… Здорово, правда?": "New adventures, new friends... Great, isn't it?",
  "У меня для тебя кое-что есть.": "I have something for you.",
  "П-прости, я ещё не совсем проснулась.": "S—Sorry, I'm not fully awake yet.",
  "Сейчас или никогда. Плечом к плечу со мной!": "It's now or never. Fight with me!",
  "Покажи свою храбрость.": "Show your courage.",
  "Спасибо… Я буду твёрдо стоять за свой народ.": "Thank you... I will stand firm for my people.",
  "Усилить оборону.": "Strengthen our defenses.",
  "Кольцо в виде тигра или дракона?": "Should the locket and the carrying ring be dragon- or tiger-shaped?",
  "Сколько приёмов ты сможешь отразить?": "So, how many of my moves can you block?",
  "Мой меч хорошо обучен. Пора испытать его в деле.": "My swordplay is ready. Time to put it to the test.",
  "Кажется, кому-то нужен доктор!": "Looks like somebody needs a doctor!",
  "Хочешь конфетку? Нет? Тогда я сама съем.": "Do you want candy? No? Then I'll have it.",
  "Скажи «а-а»!": "Say \"ahhhh!\"",
  "Проводник лучше всех!": "The conductor is the best!",
  "Если я рядом, разве мы можем проиграть?": "With me out here, how can we lose~",
  "Отойди. Я не хочу раздувать конфликт.": "Step aside, I have no interest in stoking conflict.",
  "Время пришло.": "The time is now.",
  "Подарок от звёзд!": "A gift from the stars~",
  "Цели как звёзды: они ближе, чем кажется.": "Goals are like the stars — we'll reach them eventually.",
  "Меч всегда должен быть наточен.": "You should keep your sword sharp at all times.",
  "Она примерно на 70% похожа на меня в детстве.": "It's about seventy percent similar to how I looked as a child.",
  "Эта песня только для вас.": "This song's just for you~",
  "Сделайте погромче!": "Turn up the volume!",
  "Самое лучшее ещё впереди!": "The best is yet to come!",
  "Сампо Коски всегда заботится о друзьях.": "Sampo Koski always takes care of his friends.",
  "Кроты выходят из норы! В атаку, храбрые Кроты!": "Moles, Moles, leaving our holes, brave Moles, charge as a whole!",
  "Всё готово? Начнём сегодняшний рапорт.": "You ready? Let's start the records for the day.",
  "Получены данные о противнике.": "Enemy data secured.",
  "Каждый шаг тоже часть приключения.": "Every step is just a part of the adventure.",
  "Турнир начинается? Прекрасно! Дай мне разогреться.": "The tournament's starting? Great! Let me get warmed up.",
  "Где аплодисменты?": "Where's the applause?",
  "Рано или поздно я войду в историю!": "Sooner or later, I'll make my mark in history!",
  "Феникс, восстань!": "Rise, phoenix!",
  "Книга основана на событиях моей жизни.": "The story is based on my life.",
  "Признаёшься ли ты в содеянном?": "Do you admit this crime?",
  "Час пробил.": "It's time.",
  "Почти любое дело можно решить переговорами.": "Peace is the best for business.",
  "А что если нам подружиться?": "Let's be friends, shall we?",
